#include "stdlib/math/base/special/coversin.h"
#include "stdlib/math/base/special/sin.h"
#include "stdlib/math/base/special/cos.h"

/**
* Computes the coversed sine.
*
* @param x    input value (in radians)
* @return     coversed sine
*
* @example
* double y = stdlib_base_coversin( 3.141592653589793 / 2.0 );
* // returns 0.0
*/
double stdlib_base_coversin( const double x ) {
	double s;
	double c;

	s = stdlib_base_sin( x );
	if ( s > 0.0 ) {
		// Where `sin(x)` is close to one, `1 - sin(x)` cancels. Use `1 - sin(x) = cos(x)^2 / (1 + sin(x))` where `sin(x) > 0`, since `cos(x)` is computed with full relative accuracy near its zeros and the denominator does not cancel:
		c = stdlib_base_cos( x );
		return ( c * c ) / ( 1.0 + s );
	}
	return 1.0 - s;
}
